insert into grammar_practice_questions
  (id, level_id, lesson_id, prompt_jp, options, correct_index, explanation_vi, source, source_ref)
values
  ('66aee45f-b34a-591b-8cab-f124f0037cc4'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, 'この度は、（　　）、まことにありがとうございます。', '["ご来社くださり", "ご来社いたしまして", "ご来社してあげて", "ご来社されたら"]'::jsonb, 0, '「ご〜くださる」là kính ngữ cho hành động của khách (đến công ty) và đi kèm lời cảm ơn. 「いたす」là khiêm nhường, chỉ dùng cho hành động của mình; 「〜てあげる」không dùng với khách; 「〜たら」là điều kiện nên không hợp với lời cảm ơn.', 'book', '第1課 練習① 第1項'),
  ('1db3c6e5-f47c-5fcb-9dd9-fdf0543bd81d'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, '私は、弊社のIT部門でプロジェクトを管理しています。小巻（　　）。', '["とおっしゃいます", "と申します", "と存じます", "と言われます"]'::jsonb, 1, 'Khi tự giới thiệu tên mình dùng khiêm nhường ngữ「と申します」. 「とおっしゃいます」và 「と言われます」là cách nói về người khác; 「と存じます」nghĩa là “tôi nghĩ”.', 'book', '第1課 練習① 第2項'),
  ('9ca07abf-8b71-567b-a8ca-4ac726165f0b'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, '私は、日本の（　　）システム開発プロジェクトを主に担当しております。', '["お客様向けに", "お客様向けで", "お客様向けの", "お客様向けと"]'::jsonb, 2, '「N向けの + danh từ」: dành cho N, bổ nghĩa cho danh từ 「システム開発プロジェクト」nên cần 「の」. Các trợ từ còn lại không nối được với danh từ phía sau.', 'book', '第1課 練習① 第3項'),
  ('10752555-aec0-50d8-abeb-af3d0024a4af'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, '今回のプロジェクトのPMを（　　）、アンと申します。', '["つとめることがありました", "つとめたことになりました", "つとめていることになりました", "つとめることになりました"]'::jsonb, 3, '「〜ことになりました」nói về việc đã được quyết định/phân công (ở đây là được giao làm PM). 「ことがありました」là “đã từng có lần”; 「たことになりました」là “coi như đã làm”; 「ていることになりました」là “coi như đang làm” — đều sai ý.', 'book', '第1課 練習① 第4項'),
  ('3552800d-e897-5a14-8317-1e766770edf7'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000001'::uuid, 'リーが後任として担当する（　　）。', '["ことになっております", "ことができております", "ようになっております", "ことだと思っております"]'::jsonb, 0, '「〜ことになっている」: việc đã được sắp xếp/quyết định sẽ làm, dùng để thông báo kế hoạch. 「ことができる」là khả năng, 「ようになる」là thay đổi thói quen/khả năng, 「ことだと思う」là suy nghĩ cá nhân.', 'book', '第1課 練習① 第5項'),
  ('8a105847-7ed4-5e34-aac5-df985ef44788'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, 'では、プロジェクトのキックオフミーティングを（　　）。', '["始めたがっています", "始めたいと思います", "始めたくないと思います", "始めさせたいと思います"]'::jsonb, 1, 'Người nói đề nghị bắt đầu họp nên dùng 「V-たいと思います」(ngôi thứ nhất). 「たがる」dùng cho ý muốn của người khác; 「たくない」ngược nghĩa; 「させたい」là muốn bắt ai đó làm.', 'book', '第2課 練習① 第1項'),
  ('72f85080-3e04-550d-983d-8068d3a78574'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, 'まず、本日のアジェンダ（　　）。', '["について説明なさいます", "について説明していらっしゃいます", "について説明いたします", "について説明していただきます"]'::jsonb, 2, 'Người nói tự trình bày nên dùng khiêm nhường ngữ「いたします」. 「なさいます」「していらっしゃいます」là kính ngữ cho người khác; 「していただきます」là “được (ai đó) giải thích cho”.', 'book', '第2課 練習① 第2項'),
  ('26b1c3a8-f897-55c7-880e-5bcf2cb0697d'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, 'プロジェクト見積書（　　）ありがとうございます。', '["のお確認", "をご確認", "にご確認", "のご確認"]'::jsonb, 3, 'Danh từ gốc Hán như 「確認」đi với 「ご」(ご確認), không dùng 「お」. Nối với danh từ trước bằng 「の」để thành cụm danh từ rồi mới cảm ơn: 「〜のご確認ありがとうございます」.', 'book', '第2課 練習① 第4項'),
  ('15ab42e8-1e0f-5a66-920d-e19193aee814'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000002'::uuid, '既存システム（　　）、WebGLを取り入れて機能追加と変更をします。', '["をベースに", "をベースで", "がベースに", "をベースへ"]'::jsonb, 0, 'Mẫu cố định 「N をベースに」: dựa trên N. Trợ từ 「を」trước ベース và 「に」sau ベース không thay được bằng で/へ hay đổi が.', 'book', '第2課 練習① 第5項'),
  ('03b5f46b-0455-519a-9a38-dda1abcc6127'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, 'ロジックに合わせて直したほうがよいものがありましたら、（　　）。', '["教えてあげればと思います", "教えていただければと思います", "教えさせていただければと思います", "教えていただいたと思います"]'::jsonb, 1, 'Nhờ người khác cho biết dùng 「V-ていただければと思います」(mềm, lịch sự). 「てあげる」nghĩa là mình làm cho người khác; 「させていただく」là mình xin phép làm; 「いただいたと思います」là nói về việc đã nhận trong quá khứ.', 'book', '第3課 練習① 第1項'),
  ('9a673e36-c7d6-5258-8ce5-ad7dfc5d6c14'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, '前回と（　　）、それで問題ないと思います。', '["変わらないのに", "変わらなくても", "変わらないので", "変わらないけれど"]'::jsonb, 2, 'Vế sau 「それで問題ないと思います」là kết luận từ lý do nên dùng 「ので」(vì). 「のに」「ても」「けれど」đều là quan hệ tương phản, không hợp ý nghĩa.', 'book', '第3課 練習① 第2項'),
  ('3b3fc24f-4308-567e-a4e1-ff8bd1be36b1'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, 'UATをサポートするため、3月にオンサイトする（　　）。', '["ことが提案します", "ことに提案します", "ことで提案します", "ことを提案します"]'::jsonb, 3, '「提案する」là ngoại động từ, nội dung đề xuất làm tân ngữ nên dùng 「を」: 「〜ことを提案します」.', 'book', '第3課 練習① 第3項'),
  ('076a04a4-ac5f-53c8-9a33-51442f6b7696'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000003'::uuid, '（　　）、両社で進め方がわかると考えています。', '["そうすれば", "そうしても", "そうしなければ", "そうするだけ"]'::jsonb, 0, '「そうすれば」(nếu làm như vậy thì...) dẫn tới kết quả mong đợi. 「そうしても」là “dù làm vậy”; 「そうしなければ」là “nếu không làm vậy”; cả hai đều ngược ý của câu.', 'book', '第3課 練習① 第4項'),
  ('e4091b9a-cfe1-56f9-bf88-53bc2b4237e2'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, 'ここまでプロジェクト概要と開発手法について（　　）、何かご質問はありますか。', '["説明しますが", "説明しましたが", "説明させましたが", "説明されましたが"]'::jsonb, 1, '「ここまで」chỉ phần đã trình bày xong nên dùng quá khứ 「説明しました」. 「しますが」là tương lai; 「させました」là bắt ai đó giải thích; 「されました」là bị động/kính ngữ cho người khác.', 'book', '第4課 練習① 第1項'),
  ('5cf26e91-5303-5deb-9580-c3e3d6c0e0d1'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '（　　）、体制とメンバーについて紹介いたします。', '["ご質問がなくても", "ご質問がないのに", "ご質問がなければ", "ご質問がなければこそ"]'::jsonb, 2, '「〜がなければ」: nếu không có ... thì (điều kiện) rồi chuyển sang nội dung tiếp theo. 「なくても」là “dù không có”, 「ないのに」là “mặc dù không có”, đều sai logic.', 'book', '第4課 練習① 第2項'),
  ('16929bf1-13a7-5186-a12f-ae1c8961d40f'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '課題などは小巻様と確認（　　）ですが、間違いないでしょうか。', '["すればよいという意見", "するべきではないという理解", "すればよかったという理解", "すればよいという理解"]'::jsonb, 3, 'Xác nhận lại cách hiểu: 「〜という理解ですが、間違いないでしょうか」. 「意見」là quan điểm chứ không phải cách hiểu cần xác nhận; 「べきではない」ngược nghĩa; 「よかった」là quá khứ.', 'book', '第4課 練習① 第3項'),
  ('73ac61cd-bce9-5e48-9a98-f448bfca7d4c'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '私がそれらの情報をまとめて、（　　）。', '["小巻様に報告します", "小巻様を報告します", "小巻様が報告します", "小巻様で報告します"]'::jsonb, 0, '「報告する」đối tượng nhận báo cáo đi với 「に」: 「〜に報告します」. 「が」sẽ đổi chủ thể, 「を」「で」không đúng vai trò.', 'book', '第4課 練習① 第4項'),
  ('ae4763b4-f420-57ba-acdc-20b854f3e431'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000004'::uuid, '場合によっては、オンサイトが不要になる（　　）。', '["はずです", "かもしれません", "に違いありません", "ことになっています"]'::jsonb, 1, '「場合によっては」(tùy trường hợp) đi với khả năng không chắc chắn: 「かもしれません」. 「に違いありません」là khẳng định chắc chắn, 「はずです」là dự đoán có căn cứ, 「ことになっています」là quy định.', 'book', '第4課 練習① 第5項'),
  ('57848262-2284-5bba-9a7f-3a78acf6d577'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, '紹介します。UATのサポートをするために（　　）ナムさんです。', '["お越しいたした", "お越ししてあげた", "お越しくださった", "お越しして"]'::jsonb, 2, 'Người được giới thiệu là khách nên dùng 「お越しくださった」(kính ngữ + くださる). 「いたす」là khiêm nhường cho mình; 「してあげた」không dùng với khách; 「お越しして」sai dạng.', 'book', '第5課 練習① 第1項'),
  ('f1c42f9a-075a-55b9-803e-fc948d7b8912'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, '本日よりお世話になります。ベトナムから（　　）、リーと申します。', '["いらっしゃいました", "お越しになりました", "召し上がりました", "参りました"]'::jsonb, 3, 'Tự giới thiệu về mình dùng khiêm nhường ngữ 「参りました」(来ました). 「いらっしゃいました」「お越しになりました」là kính ngữ cho người khác; 「召し上がりました」nghĩa là “đã ăn/uống” (kính ngữ).', 'book', '第5課 練習① 第2項'),
  ('8ac906d9-93f7-5f5f-a80c-f5bc3cf8ff67'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, 'オンサイト（　　）、至らない点もあるかと思いますが、どうぞよろしくお願いいたします。', '["は初めてですので", "は初めてなのに", "は初めてでも", "は初めてだけど"]'::jsonb, 0, 'Nêu lý do để xin sự giúp đỡ: 「初めてですので、〜かと思いますが」. 「のに」「でも」「けど」là tương phản nên không nối được với lời xin chiếu cố.', 'book', '第5課 練習① 第3項'),
  ('9da8f85a-2ced-5b32-bec0-16719632df55'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000005'::uuid, '（　　）、今後の予定は決まっていますか。', '["だから", "ところで", "しかも", "したがって"]'::jsonb, 1, '「ところで」dùng để chuyển sang chủ đề khác (nhân tiện). 「だから」「したがって」nêu kết quả, 「しかも」thêm ý — không hợp để mở câu hỏi mới.', 'book', '第5課 練習① 第4項'),
  ('2997e46b-f99b-543e-af72-1d2f0186b746'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, '後で予約サイトのリンクを（　　）。', '["送ってありますね", "送ってみますね", "送っておきますね", "送っていますね"]'::jsonb, 2, '「V-ておく」: làm sẵn (chuẩn bị trước). 「てある」là trạng thái đã làm xong, 「てみる」là thử làm, 「ている」là đang làm — không hợp với 「後で」(lát nữa).', 'book', '第6課 練習① 第1項'),
  ('6d34538b-e919-5193-b6bd-0312944f52d9'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, '給湯室のとなりにあるコピー機は自由に（　　）。', '["お使いしてください", "お使いになります", "お使いなさっています", "お使いください"]'::jsonb, 3, 'Mời người khác dùng: 「お + V-ます + ください」. 「お使いして」là khiêm nhường nên sai khi nói với người nghe; 「お使いになります」「お使いなさっています」là câu tường thuật, không phải lời mời.', 'book', '第6課 練習① 第2項'),
  ('eb1eb5fc-8b8c-5012-bc64-485f9ed96708'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, '席を離れるときは、机の上に資料などを（　　）しないようにしてください。', '["置いたままに", "置いたばかりに", "置いたとおりに", "置いたあとに"]'::jsonb, 0, '「V-たままにする」: để nguyên trạng thái. Cấu trúc 「〜たままにしないようにしてください」là lời nhắc đừng để nguyên. Các dạng còn lại không kết hợp được với 「にしない」.', 'book', '第6課 練習① 第3項'),
  ('cf3617a7-21d7-5907-8454-3be586842958'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000006'::uuid, 'ベトナムにいる間に、必要なデータはバックアップを（　　）。', '["取ってしまいます", "取ってあります", "取ってみます", "取ってきます"]'::jsonb, 1, '「V-てある」: đã làm sẵn và kết quả vẫn còn (đã sao lưu sẵn). 「てしまう」「てみる」「てくる」có nghĩa khác và không diễn tả kết quả đã chuẩn bị.', 'book', '第6課 練習① 第4項'),
  ('3b871fe6-e932-57ee-9804-bc72b74a4eab'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, 'プロジェクトのメンバーが全員（　　）、要件の説明会を始めたいと思います。', '["そろいましたのに", "そろいましたけど", "そろいましたので", "そろいましても"]'::jsonb, 2, 'Nêu lý do để bắt đầu họp: 「〜ましたので」(vì đã...). 「のに」「けど」「ても」đều mang ý tương phản nên mâu thuẫn với việc bắt đầu họp.', 'book', '第7課 練習① 第1項'),
  ('ec7321d6-5f93-5879-84f2-4a308e078023'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, 'キックオフミーティングで（　　）、一部機能の追加・修正を行います。', '["説明する通り", "説明したばかり", "説明させる通り", "説明した通り"]'::jsonb, 3, '「V-た通り」: như đã làm. Kickoff đã diễn ra nên dùng quá khứ. 「説明する通り」là “như sẽ giải thích”, 「たばかり」là “vừa mới”, 「させる通り」sai nghĩa.', 'book', '第7課 練習① 第2項'),
  ('0c41a046-3b0a-5a19-bf82-4877a7076480'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, '皆さん（　　）なじみのあるものだと思います。', '["にとっては", "によっては", "のためには", "をめぐっては"]'::jsonb, 0, '「Nにとって」: đối với N (đánh giá từ góc nhìn của N). 「によっては」là “tùy theo”, 「のためには」là “để...”, 「をめぐって」là “xoay quanh”.', 'book', '第7課 練習① 第3項'),
  ('21d4d4e6-1cf1-59a0-a728-31faf22809b2'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000007'::uuid, '疑問点がでてきたら、（　　）。', '["確認してください", "確認させてください", "確認なさってください", "確認してあげてください"]'::jsonb, 1, '「V-させてください」: xin phép để mình làm (cho tôi xác nhận). Các dạng khác nghĩa là yêu cầu/đề nghị người nghe xác nhận, ngược với ý định của người nói.', 'book', '第7課 練習① 第5項'),
  ('dadadb65-9100-5415-a785-d7e8b04a4944'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000008'::uuid, '内容は体制とレポートライン（　　）。', '["に2つです", "を2つです", "の2つです", "が2つです"]'::jsonb, 2, 'Liệt kê nội dung: 「AとBの2つです」, 「の」nối cụm liệt kê với số lượng. Các trợ từ khác không tạo được cụm danh từ cho 「2つ」.', 'book', '第8課 練習① 第1項'),
  ('554baf92-fc59-5e42-9c84-f75ba4c7284b'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000008'::uuid, '現在は、UAT サポートとバグ修正を（　　）。', '["進んでいます", "進めてあります", "進められています", "進めています"]'::jsonb, 3, '「〜を進める」(tha động từ) + ています: đang tiến hành. 「進む」là tự động từ không đi với 「を」; 「てあります」là đã chuẩn bị xong; 「進められています」là bị động.', 'book', '第8課 練習① 第2項'),
  ('9241f612-7e53-5f3c-a586-59798517536e'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000008'::uuid, '進捗の詳細は WBS ファイルを（　　）。', '["ご確認ください", "ご確認します", "ご確認になります", "ご確認いたします"]'::jsonb, 0, 'Đề nghị người nghe xem tài liệu: 「ご + 漢語 + ください」. 「ご確認します/いたします」là mình sẽ xác nhận, 「ご確認になります」là câu tường thuật.', 'book', '第8課 練習① 第4項'),
  ('863330bc-4164-5ec6-afa9-9fdad0da586b'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, '海底ケーブルに問題がある（　　）、状況を教えてもらえますか。', '["と聞かれていますが", "と聞いていますが", "と聞かせていますが", "と聞いてしまいますが"]'::jsonb, 1, '「〜と聞いています」: nghe nói rằng... (nguồn tin). 「聞かれて」là bị hỏi, 「聞かせて」là cho nghe, 「聞いてしまう」là lỡ nghe.', 'book', '第9課 練習① 第1項'),
  ('bd4d0d23-390c-53bd-9941-75f2643b1a73'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, '確認不足（　　）、手戻りが発生したのですね。', '["を原因で", "が原因に", "が原因で", "が原因と"]'::jsonb, 2, 'Mẫu 「Nが原因で、〜」: do nguyên nhân là N. Các trợ từ khác không tạo được cụm chỉ nguyên nhân.', 'book', '第9課 練習① 第2項'),
  ('1ef2f5f9-ca76-5b14-a111-d565c4d5a4c8'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, 'お客様と確認（　　）、この機能が不要であることがわかりました。', '["する結果", "して結果", "しての結果", "した結果"]'::jsonb, 3, '「V-た結果」: kết quả sau khi đã làm (việc xác nhận đã xảy ra rồi). Dạng 「する結果」sai thì, các dạng còn lại sai ngữ pháp.', 'book', '第9課 練習① 第3項'),
  ('d8620a3f-373b-5893-aca3-9c88f7bfae8a'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000009'::uuid, '要件定義の遅延は今週金曜日（　　）取り戻す予定です。', '["までに", "まで", "まででも", "までで"]'::jsonb, 0, '「までに」: hạn chót, việc hoàn tất trước/đến mốc đó. 「まで」là kéo dài liên tục đến mốc, không hợp với hành động bù lại một lần.', 'book', '第9課 練習① 第5項'),
  ('719785dc-3500-5385-9eb2-fc280a6b1da8'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, 'サーバに週報を置きましたので、本日中に（　　）。', '["ご確認くださいましたか", "ご確認いただけますか", "ご確認させていただけますか", "ご確認いたしますか"]'::jsonb, 1, 'Nhờ người khác làm: 「ご〜いただけますか」. 「くださいましたか」hỏi chuyện đã xảy ra; 「させていただけますか」là xin phép mình làm; 「いたしますか」là hỏi về hành động của bản thân.', 'book', '第10課 練習① 第1項'),
  ('05181092-4af6-5dd9-8461-b49059fb7f8f'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, '必要な資料は（　　）お送りしますが、いかがですか。', '["送れる範囲に", "送れる範囲を", "送れる範囲で", "送れる範囲が"]'::jsonb, 2, '「V可能形 + 範囲で」: trong phạm vi có thể. Trợ từ 「で」chỉ giới hạn/phạm vi thực hiện; 「に」「を」「が」không diễn tả đúng ý đó.', 'book', '第10課 練習① 第2項'),
  ('77d644e0-a45f-5f0e-9a35-761bce0377dc'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, '入力機能も対象外にするというお話でしたが、今回実装するのは表示機能（　　）。', '["のみをよろしいですか", "のみにはよろしいですか", "のみへよろしいですか", "のみでよろしいですか"]'::jsonb, 3, 'Xác nhận lại: 「N のみでよろしいですか」(chỉ N là được chứ?). Trợ từ 「で」cho biết phạm vi chấp nhận; các trợ từ còn lại không đi với 「よろしい」.', 'book', '第10課 練習① 第3項'),
  ('2349a719-6abd-5506-8bfb-d78c1c6954eb'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, '理由はテストケースの件数が少なくて、品質（　　）可能性があるからです。', '["に影響を与える", "を影響する", "が影響される", "に影響させる"]'::jsonb, 0, 'Mẫu cố định 「Nに影響を与える」: gây ảnh hưởng đến N. Dạng 「を影響する」sai ngữ pháp, các dạng còn lại bị động/sai khiến làm đổi nghĩa.', 'book', '第10課 練習① 第4項'),
  ('b1e050ac-e31b-5407-9f45-b6590df441af'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000010'::uuid, 'そろそろ終了時間ですので、本日中に残りのメッセージをレビュー（　　）。', '["させていただけると幸いです", "していただけると幸いです", "していただくと幸いでした", "してあげると幸いです"]'::jsonb, 1, 'Lời nhờ trang trọng: 「V-ていただけると幸いです」. 「させて」là mình xin phép làm, 「幸いでした」sai thì, 「てあげる」là mình làm cho người khác.', 'book', '第10課 練習① 第5項'),
  ('ecd567fe-3022-525e-ae41-8f45463a6e99'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, 'ホーム画面の色は（　　）ご確認お願いします。', '["これでよいと", "これでよいのに", "これでよいか", "これでよいけど"]'::jsonb, 2, '「〜か + ご確認お願いします」: nhờ kiểm tra xem có ổn không, nên cần câu hỏi lồng 「か」. 「と」「のに」「けど」không tạo câu hỏi lồng.', 'book', '第11課 練習① 第1項'),
  ('d50516b7-46ee-511f-b1b4-b42e7b8474f2'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, 'オンサイトせずに対応する（　　）。', '["わけがないですか", "ことにはいかないですか", "はずにはいかないですか", "わけにはいかないですか"]'::jsonb, 3, '「V-るわけにはいかない」: không thể (vì lý do hoàn cảnh); ở dạng hỏi là “không thể... được sao?”. 「わけがない」là “không đời nào”, hai dạng còn lại không tồn tại.', 'book', '第11課 練習① 第3項'),
  ('a2685fc6-53b2-5e19-93cd-9e43f7f8c5a7'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, 'バグの原因を（　　）報告してください。', '["究明して", "究明すると", "究明しては", "究明したり"]'::jsonb, 0, 'Hai việc nối tiếp: 「V-て + V-てください」(tìm nguyên nhân rồi báo cáo). 「と」「ては」「たり」không tạo trình tự hành động theo yêu cầu.', 'book', '第11課 練習① 第4項'),
  ('53987f2c-001c-5c38-a71a-0b93289fa51f'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000011'::uuid, '仕様変更の場合は、一部スケジュールを調整する（　　）と思います。', '["必要に出てくる", "必要が出てくる", "必要を出てくる", "必要で出てくる"]'::jsonb, 1, 'Mẫu cố định 「〜する必要が出てくる」: phát sinh nhu cầu phải làm. Chủ ngữ của 出てくる là 必要 nên đi với 「が」.', 'book', '第11課 練習① 第5項'),
  ('84ea895b-81a4-53bf-b5d9-9be499ea8507'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000012'::uuid, '対応工数を見積もった結果、少なくとも10人日（　　）。', '["かかるつもりです", "かかるべきです", "かかる見込みです", "かかったはずです"]'::jsonb, 2, '「見込みです」: dự kiến/ước tính. 「つもり」là ý định của người nói, 「べき」là điều nên làm, 「はずだ」ở quá khứ không hợp với dự tính tương lai.', 'book', '第12課 練習① 第3項'),
  ('db9085fc-462d-5903-92b6-0521a2511cd6'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000012'::uuid, '１点（　　）、手順書にはアンインストールの手順が書いてありますか。', '["確認しておきたがっていますが", "確認しておくそうですが", "確認しておきたくないのですが", "確認しておきたいのですが"]'::jsonb, 3, 'Mở lời lịch sự để hỏi: 「確認しておきたいのですが」(muốn xác nhận trước một điểm). 「たがる」là ý muốn người khác, 「そうです」là nghe nói, 「たくない」ngược nghĩa.', 'book', '第12課 練習① 第4項'),
  ('e70da1fb-f43b-5d39-bfdf-a9fdd0351796'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000012'::uuid, '変な雑音が多くて聞こえませんので、（　　）、切ってかけなおします。', '["一旦", "一方", "一度に", "一向に"]'::jsonb, 0, '「一旦」: tạm thời, trước mắt (ngắt máy rồi gọi lại). 「一方」là mặt khác, 「一度に」là cùng một lúc, 「一向に」thường đi với phủ định.', 'book', '第12課 練習① 第5項'),
  ('edf262bc-97f1-5bb1-a2a2-a38303ef69bc'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000013'::uuid, '更新されていない情報が残っているので、後ほどまとめて（　　）。', '["送付してください", "送付させてください", "送付なさってください", "送付してあげてください"]'::jsonb, 1, 'Xin phép làm việc đó sau: 「V-させてください」. Các dạng còn lại là yêu cầu/đề nghị người nghe làm, trái với ý của người nói.', 'book', '第13課 練習① 第3項'),
  ('70531159-ff64-5d08-9591-4f9f649b7584'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000013'::uuid, '（　　）、バグの修正方法の詳細も補足しています。', '["ご要望につれて", "ご要望にとって", "ご要望に応じて", "ご要望によらず"]'::jsonb, 2, '「Nに応じて」: đáp ứng theo N (theo yêu cầu). 「につれて」là “cùng với sự thay đổi”, 「にとって」là “đối với”, 「によらず」là “bất kể”.', 'book', '第13課 練習① 第2項'),
  ('4b32a718-94de-51e6-8815-05f6b8698387'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000013'::uuid, '見積り（　　）説明した通り、端末のスペックによるものです。', '["の間に", "のうちに", "のところに", "の際に"]'::jsonb, 3, '「Nの際に」: vào dịp/lúc N (trang trọng). 「の間に」chỉ khoảng thời gian kéo dài, 「のうちに」là nhân lúc còn, 「のところに」là ở chỗ — không hợp ngữ cảnh khi báo giá.', 'book', '第13課 練習① 第5項'),
  ('45dc4eff-9044-5fb2-8a4b-44126804450c'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '制限事項（　　）、既知の課題も記載します。', '["に加えて", "に比べて", "に対して", "にとって"]'::jsonb, 0, '「Aに加えて、Bも」: ngoài A ra còn B. 「に比べて」là so sánh, 「に対して」là đối với, 「にとって」là đối với (quan điểm) — không thêm ý.', 'book', '第14課 練習① 第1項'),
  ('c090ba8a-7d81-5a19-a317-01f4e380c003'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '要求変更（　　）、両社が相談し、対応順序を決めます。', '["に比べて", "に際して", "にとって", "のわりに"]'::jsonb, 1, '「Nに際して」: khi/nhân dịp N (trang trọng, hay dùng trong tài liệu và họp). Các cụm còn lại là so sánh hoặc đánh giá, không chỉ thời điểm.', 'book', '第14課 練習① 第2項'),
  ('192b1243-0633-5b68-bd6a-73b5361be18c'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '次回の月次会議の日時（　　）連絡します。', '["が決めて、", "を決まって、", "を決めて、", "に決めて、"]'::jsonb, 2, '「決める」là tha động từ: 「Nを決める」, rồi nối sang hành động tiếp theo bằng て. 「決まる」là tự động từ nên không đi với 「を」.', 'book', '第14課 練習① 第3項'),
  ('36fc9ce0-2aca-59e0-a31f-acc414540728'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '（　　）、一昨日、今後の計画についてメールしましたが、確認していただけましたか。', '["そう言っても", "そう言うなら", "そう言ったら", "そう言えば"]'::jsonb, 3, '「そう言えば」: nhắc mới nhớ (nhớ lại chuyện liên quan). Các dạng khác là “dù nói vậy”, “nếu nói vậy”, “khi nói vậy”.', 'book', '第14課 練習① 第4項'),
  ('96262f68-1a79-51ba-8b91-5b7090c0742d'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000014'::uuid, '今回のインシデント（　　）報告書をサーバに置きました。', '["に関わる", "に関わらず", "に関わって", "に関わりを"]'::jsonb, 0, '「Nに関わる + danh từ」: liên quan đến N. 「に関わらず」nghĩa là “bất kể”, hai dạng còn lại không bổ nghĩa được cho 「報告書」.', 'book', '第14課 練習① 第5項'),
  ('0bdee47c-8f7d-5eb1-b8d1-c94a35a457b4'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, '石山さん、（　　）１年半お疲れさまでした。', '["これから", "これまで", "これでは", "これだけ"]'::jsonb, 1, '「これまで」: từ trước đến nay, kết hợp 「お疲れさまでした」để cảm ơn công sức đã qua. 「これから」là từ giờ trở đi nên không hợp.', 'book', '第15課 練習① 第1項'),
  ('cf20900b-ba44-5021-9fa6-ff98d0c79c68'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, '本年も無事に新年（　　）ことができました。', '["に迎える", "が迎える", "を迎える", "で迎える"]'::jsonb, 2, '「N を迎える」: đón N (đón năm mới), tha động từ nên đi với 「を」.', 'book', '第15課 練習① 第2項'),
  ('70770d42-ed25-5a8b-962e-9b3a82f45921'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, 'スプリントのレトロ（　　）、チームの改善点をまとめましょう。', '["に向いて", "に対して", "によって", "に向けて"]'::jsonb, 3, '「Nに向けて」: hướng tới/chuẩn bị cho N. 「に向いて」là hợp với, 「に対して」là đối với, 「によって」là tùy theo/bởi.', 'book', '第15課 練習① 第3項'),
  ('8f543b16-585d-5da5-87a8-3f326afe9757'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, 'まだ確定していませんが、テスト期間が延長される（　　）。', '["かもしれません", "はずがありません", "に違いありません", "ことになっています"]'::jsonb, 0, '「まだ確定していません」nên chỉ nêu khả năng: 「かもしれません」. 「に違いありません」là chắc chắn, 「はずがない」là không thể, 「ことになっている」là đã quy định.', 'book', '第15課 練習① 第4項'),
  ('1de86879-6b89-561f-9c98-ef638f14aec4'::uuid, (select id from jlpt_levels where code = 'IT'), '98000000-0000-0000-0000-000000000015'::uuid, '仕様が（　　）、すぐに開発に着手したいです。', '["決まったのに", "決まったら", "決まるまで", "決まれたら"]'::jsonb, 1, '「V-たら」: khi/nếu việc đó xảy ra thì ... (điều kiện). 「のに」là tương phản, 「まで」là cho đến khi, 「決まれたら」không phải dạng đúng.', 'book', '第15課 練習① 第5項')
